import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

// Dữ liệu nhân viên mẫu
const fakeEmployees = [
  { id: 1, name: 'Nguyễn Văn An', department: 'Kỹ thuật', position: 'Lập trình viên', status: 'Đang làm' },
  { id: 2, name: 'Trần Thị Bình', department: 'Marketing', position: 'Chuyên viên', status: 'Đang làm' },
  { id: 3, name: 'Lê Văn Cường', department: 'Kế toán', position: 'Kế toán viên', status: 'Nghỉ phép' },
  { id: 4, name: 'Phạm Thị Dung', department: 'Nhân sự', position: 'Chuyên viên HR', status: 'Đang làm' },
  { id: 5, name: 'Hoàng Văn Em', department: 'Kỹ thuật', position: 'Kỹ sư', status: 'Đang làm' },
];

function Employees() {
  const navigate = useNavigate();
  const [search, setSearch] = useState('');

  const filtered = fakeEmployees.filter((e) =>
    e.name.toLowerCase().includes(search.toLowerCase()) ||
    e.department.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Nhân viên</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '20px' }}>
        Danh sách toàn bộ nhân viên trong hệ thống.
      </p>

      {/* Thanh tìm kiếm */}
      <div style={{ marginBottom: '16px' }}>
        <input
          type="text"
          placeholder="Tìm kiếm theo tên hoặc phòng ban..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{
            padding: '8px 12px',
            border: '1px solid #ccc',
            borderRadius: '4px',
            fontSize: '14px',
            width: '300px'
          }}
        />
      </div>

      {/* Bảng nhân viên */}
      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8f9fa', borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>STT</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Họ tên</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Phòng ban</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Chức vụ</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Trạng thái</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Thao tác</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((emp, index) => (
              <tr key={emp.id} style={{ borderBottom: '1px solid #f0f0f0' }}>
                <td style={{ padding: '12px 16px', color: '#888' }}>{index + 1}</td>
                <td style={{ padding: '12px 16px', color: '#222' }}>{emp.name}</td>
                <td style={{ padding: '12px 16px', color: '#555' }}>{emp.department}</td>
                <td style={{ padding: '12px 16px', color: '#555' }}>{emp.position}</td>
                <td style={{ padding: '12px 16px' }}>
                  <span style={{
                    padding: '2px 8px',
                    borderRadius: '12px',
                    fontSize: '12px',
                    backgroundColor: emp.status === 'Đang làm' ? '#dcfce7' : '#fef9c3',
                    color: emp.status === 'Đang làm' ? '#16a34a' : '#a16207'
                  }}>
                    {emp.status}
                  </span>
                </td>
                <td style={{ padding: '12px 16px' }}>
                  <button
                    onClick={() => navigate(`/employees/${emp.id}`)}
                    style={{
                      padding: '4px 10px',
                      fontSize: '13px',
                      border: '1px solid #2563eb',
                      borderRadius: '4px',
                      backgroundColor: '#fff',
                      color: '#2563eb',
                      cursor: 'pointer'
                    }}
                  >
                    Xem
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} style={{ padding: '20px', textAlign: 'center', color: '#aaa' }}>
                  Không tìm thấy nhân viên nào.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Employees;
